public class ProblemE {

	static final long MOD = 998244353;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		long m = sc.nextLong();
		long n = sc.nextLong();
		long l = sc.nextLong();
		long r = sc.nextLong();
		sc.close();

		long total = m * n;
