#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long fastPower(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long a, long long m) {
    return fastPower(a, m - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long m, n, l, r;
    cin >> m >> n >> l >> r;

    long long total = m * n;
    long long length = r - l + 1;

    long long result = fastPower(length, total);
    if (total % 2 != 0) {
        cout << result << "\n";
    } else {
        if (length % 2 == 0)
            cout << (result * modInverse(2, MOD)) % MOD << "\n";
        else
            cout << (((result + 1) % MOD) * modInverse(2, MOD)) % MOD << "\n";
    }
    return 0;
}
